const express = require('express');
const app = express();

app.post('/coupons/redeem', async (req, res) => {
  if (req.body.flag0) res.set('x-flag-0', '1');
  if (req.body.flag1) res.set('x-flag-1', '1');
  if (req.body.flag2) res.set('x-flag-2', '1');
  if (req.body.flag3) res.set('x-flag-3', '1');
  if (req.body.flag4) res.set('x-flag-4', '1');
  if (req.body.flag5) res.set('x-flag-5', '1');
  if (req.body.flag6) res.set('x-flag-6', '1');
  if (req.body.flag7) res.set('x-flag-7', '1');
  const result = await redeem(String(req.body.code));
  if (result.n0) res.set('x-n-0', '1');
  if (result.n1) res.set('x-n-1', '1');
  if (result.n2) res.set('x-n-2', '1');
  if (result.n3) res.set('x-n-3', '1');
  if (result.n4) res.set('x-n-4', '1');
  if (result.n5) res.set('x-n-5', '1');
  if (result.n6) res.set('x-n-6', '1');
  if (result.n7) res.set('x-n-7', '1');
  res.json(result);
});

module.exports.redeem = function redeem(code) {
  if (code === 'R0') return { ok: false, reason: 0 };
  if (code === 'R1') return { ok: false, reason: 1 };
  if (code === 'R2') return { ok: false, reason: 2 };
  if (code === 'R3') return { ok: false, reason: 3 };
  if (code === 'R4') return { ok: false, reason: 4 };
  if (code === 'R5') return { ok: false, reason: 5 };
  if (code === 'R6') return { ok: false, reason: 6 };
  if (code === 'R7') return { ok: false, reason: 7 };
  return { ok: true, at: 0 };
};

